{
  "bioavailability_prediction": "high",
  "confidence": "high",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C21", "C51", "C37", "C32", "C54", "C59", "C57", "C65", "C64"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C21", "C51", "C37", "C32", "C54", "C59", "C65", "C64"],
  "claims": [
    {
      "claim": "The query is carbamazepine, a neutral, lipophilic, low-MW tricyclic urea; the closest gold-context analog thalidomide showed probably high absolute oral bioavailability (80–100%) at low doses in fasting volunteers, supporting F ≥ 20%.",
      "card_ids": ["C21"]
    },
    {
      "claim": "L4 provides direct intestinal absorption evidence for the same dibenzazepine carboxamide scaffold: oxcarbazepine absorption was essentially complete after a single oral radiolabeled dose in healthy volunteers, supporting high intestinal absorption for carbamazepine.",
      "card_ids": ["C51"]
    },
    {
      "claim": "L3 oral exposure records show measurable systemic exposure after oral dosing of carbamazepine-scaffold drugs: carbamazepine-10,11-epoxide AUC12 was 9.98 µg·h/mL after oral carbamazepine 200 mg BID, and fed-state Cmax of the eslicarbazepine metabolite was 12.8 µg/mL after oral eslicarbazepine acetate, indicating oral absorption is not impaired in the fed state.",
      "card_ids": ["C37", "C32"]
    },
    {
      "claim": "L5 Caco-2 bidirectional records for neutral lipophilic aromatic amide/urea/heterocycle compounds show high passive permeability and low efflux ratios (ER ≈ 0.96–1.23), indicating no significant gut-wall efflux for this compound class; these are mechanistic, not direct carbamazepine F measurements.",
      "card_ids": ["C54", "C59", "C57", "C65", "C64"]
    },
    {
      "claim": "No affirmative threshold-relevant evidence supports F < 20%; the low-dissolution record C46 is for an unrelated molecule (OIB) and is not used as evidence against carbamazepine.",
      "card_ids": ["C46"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C54", "C55", "C56", "C57", "C58", "C59", "C60", "C61", "C62", "C63", "C64", "C65"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for carbamazepine itself is supplied; C51 is oxcarbazepine absorption, not an F value.",
    "No fed-state-specific F for carbamazepine; C32 is fed but for eslicarbazepine acetate metabolite exposure.",
    "No direct carbamazepine Caco-2/efflux or intestinal metabolism record; L5 records are for other neutral lipophilic compounds.",
    "First-pass metabolism and systemic clearance are not quantified; carbamazepine is known to be metabolized, but no record establishes F < 20%.",
    "Several L5 cards are duplicate records of the same assay (e.g., tryptanthrin at 5/10 µM) and are not independent votes.",
    "Low-solubility/dissolution records are for unrelated molecules and are not transferable."
  ],
  "decision_summary": "Prediction high: carbamazepine is a neutral lipophilic low-MW tricyclic urea with favorable passive permeability; the closest analog thalidomide and same-scaffold oxcarbazepine absorption support F ≥ 20%. L5 adds Caco-2 evidence of high permeability and minimal efflux for related neutral lipophilic compounds, reinforcing the high prediction. No affirmative evidence supports F < 20%; fed-state-specific direct F and carbamazepine-specific intestinal metabolism remain gaps."
}

